hints.text:
Un lector de códigos postales quiere el código postal más frecuente entre los pedidos de un día, con desempate alfabético.

function codigoMasFrecuente(pedidos) {
  const conteo = new Map();
  for (let i = 0; i < pedidos.length; i++) {
    const cp = pedidos[i].codigoPostal;
    conteo.set(cp, (conteo.get(cp) || 0) + 1);
  }
  let mejor = null;
  let mejorConteo = 0;
  for (const [cp, n] of conteo) {
    if (n > mejorConteo || (n === mejorConteo && cp < mejor)) {
      mejor = cp;
      mejorConteo = n;
    }
  }
  return mejor;
}

El cp < mejor es el desempate alfabético. El mejorConteo evita tener que volver a consultar el mapa.
